export const POS_BLEED_LINE_MARGIN_PX = 16;

export const POS_BAR_EDGE_INSET_FROM_BLEED_PX = 20;

export const POS_CHART_Y_AXIS_WIDTH_PX = 16;
export const POS_BAR_WIDTH_PX = 40;
export const POS_BAR_INNER_GAP_PX = 2;

export const POS_CHART_LAYOUT_PAD_LEFT_PX =
  POS_BLEED_LINE_MARGIN_PX +
  POS_BAR_EDGE_INSET_FROM_BLEED_PX -
  POS_CHART_Y_AXIS_WIDTH_PX;

export const POS_CHART_LAYOUT_PAD_RIGHT_PX =
  POS_BLEED_LINE_MARGIN_PX + POS_BAR_EDGE_INSET_FROM_BLEED_PX;

export const POS_COMPARISON_GRID_PAD_LEFT_PX =
  POS_CHART_LAYOUT_PAD_LEFT_PX + POS_CHART_Y_AXIS_WIDTH_PX;

export const POS_COMPARISON_GRID_PAD_RIGHT_PX = POS_CHART_LAYOUT_PAD_RIGHT_PX;

export const POS_BAR_PLOT_TARGET_HEIGHT_PX = 317;

export const POS_DATALABEL_OFFSET_PX = 4;
export const POS_DATALABEL_FONT_SIZE_PX = 10;
export const POS_POSITIVE_BAR_DATALABEL_CLEARANCE_PX = 11;
export const POS_NEGATIVE_BAR_DATALABEL_CLEARANCE_PX = 11;

/** Canvas headroom above chartArea for positive datalabels (offset + font + clearance). */
export const POS_POSITIVE_DATALABEL_HEADROOM_PX =
  POS_POSITIVE_BAR_DATALABEL_CLEARANCE_PX +
  POS_DATALABEL_OFFSET_PX +
  POS_DATALABEL_FONT_SIZE_PX;

/** Headroom above plot for datalabels on tall positive bars (legend sits outside canvas). */
export const POS_CHART_LAYOUT_TOP_PX = POS_POSITIVE_DATALABEL_HEADROOM_PX;

export const POS_CHART_X_LABEL_BAND_BUDGET_PX = 0;

export const POS_CHART_CANVAS_HEIGHT_PX =
  POS_CHART_LAYOUT_TOP_PX +
  POS_BAR_PLOT_TARGET_HEIGHT_PX +
  POS_CHART_X_LABEL_BAND_BUDGET_PX;

export const POS_CONTENT_MIN_HEIGHT_PX = POS_CHART_CANVAS_HEIGHT_PX + 72 + 48;

export const POS_COMPARISON_GRID_INSET_OFFSET_PX = 27;
